		private void Error_ExpectingTypeName(Expression expr)
		{
			if (expr is Invocation)
			{
				report.Error(1002, expr.Location, "Expecting `;'");
			}
			else
			{
				expr.Error_InvalidExpressionStatement(report);
			}
		}

